<?php if (!defined('ABSPATH')) { exit; } class ei_Relations { const SERVER = 'https://member.eitheme.com'; private $id = 'IKMDM3PMSS'; private $api; private $host; private $code = ''; private $key; private $data = []; private static $instance = null; public static function instance() { if (is_null(self::$instance)) { self::$instance = new self(); } return self::$instance; } public function initialization() { global $eionup, $eion, $eimatch; $eion = $this->status == 200 ? true : false; $eionup = $eion && !$this->is_exp ? true : false; $this->data(); $eimatch = $this->host == preg_replace('(^https?://)', '', site_url()); } public function __construct() { $this->api = self::SERVER . '/wp-json/salesloo/v1/file/license'; $this->host = preg_replace('(^https?://)', '', site_url()); $this->key = '__eiprolcns'; $this->data(); } public function encrypt($string) { $secret_key = AUTH_KEY; $secret_iv = AUTH_SALT; $encrypt_method = "AES-256-CBC"; $key = hash('sha256', $secret_key); $iv = substr(hash('sha256', $secret_iv), 0, 16); return base64_encode(openssl_encrypt($string, $encrypt_method, $key, 0, $iv)); } public function decrypt($string) { $secret_key = AUTH_KEY; $secret_iv = AUTH_SALT; $encrypt_method = "AES-256-CBC"; $key = hash('sha256', $secret_key); $iv = substr(hash('sha256', $secret_iv), 0, 16); return openssl_decrypt(base64_decode($string), $encrypt_method, $key, 0, $iv); } public function data() { $option = get_option($this->key); if (empty($option)) return $this; $this->data = json_decode($this->decrypt($option), true); return $this; } public function __get($name) { $value = NULL; if (array_key_exists($name, (array)$this->data)) $value = maybe_unserialize($this->data[$name]); return $name == 'status' ? intval($value) : $value; } private function update_option($result) { wp_cache_delete($this->key, 'options'); if (isset($result['status']) && $result['status'] == 402) { $data = $this->data; $data['is_exp'] = 1; $data['message'] = $result['message']; update_option($this->key, $this->encrypt(json_encode($data))); } else { update_option($this->key, $this->encrypt(json_encode($result))); } } public function menu() { add_menu_page(__('eiPro', 'eipro-master'), __('eiPro License', 'eipro-master'), 'manage_options', 'eipro-master', [$this, 'page'], 'dashicons-admin-network', 2); } public function page() { echo '<div class="wrap relation-wrap">'; echo '<form action="" method="post" enctype="multipart/form-data" style="margin-top:5px">'; wp_nonce_field('__eipro_activate', '__activate'); $readonly = $this->isOn() ? 'readonly' : ''; $value = $this->isOn() && $this->purchase_code ? substr_replace($this->purchase_code, '************************', 3, 24) : ''; $this->data(); if ($this->status == 200) { if ($this->is_exp) { echo '<h2>' . __('License Status : <span class="inactive">Expired</span>', 'eipro-master') . '</h2>'; } else { echo '<h2>' . __('License Status : <span>Active</span>', 'eipro-master') . '</h2>'; } } else { echo '<h2>' . __('License Status : <span class="inactive">Inactive</span>', 'eipro-master') . '</h2>'; } ob_start(); ?> <div class="eipro-field default"> <div class="eipro-field-label"><label><?php _e('Purchase Code', 'eipro-master'); ?></label></div> <div class="eipro-field-input"> <div class="eipro-field__text"><input type="text" name="purchase_code" class="regular-text" value="<?php echo $value; ?>" placeholder="---" autocomplete="off" <?php echo $readonly; ?>></div> </div> </div> <div class="eipro-field default"> <div class="eipro-field-label">&nbsp;</div> <div class="eipro-field-input"> <div class="eipro-field__text"><?php if (!$this->isOn()): ?><input type="submit" class="button button-primary" name="action" value="Activate"><?php else: ?><input type="submit" class="button button-primary" name="action" value="Deactivate"><?php endif; ?><p class="description"><?php echo sprintf('<a href="https://member.eitheme.com/dashboard/" target="__blank">%s</a> %s', __('Click Here', 'eipro-master'), __('to get purchase code')); ?></p> </div> </div> </div> <?php $html = ob_get_clean(); if ($this->status == 200 && !$this->is_exp) { $information = $this->message; $information .= '<br/> ' . sprintf(__('Your License expired on: %s', 'eipro-master'), $this->expired_at); $information .= '<br/>' . sprintf(__('Your license has a limit of %s and be used %s', 'eipro-master'), $this->license['limit'], $this->license['used']); echo $information ? '<div class="notice notice-info ei-lbl"><p>' . $information . '</p></div>' : ''; } elseif ($this->status == 200 && $this->is_exp) { $information = $this->message; echo $information ? '<div class="notice notice-info ei-lbl"><p>' . $information . '</p></div>' : ''; } echo $html; echo '</form>'; echo do_shortcode('[ei_general]'); echo '</div>'; } public function on_save_action() { if (isset($_POST['__activate']) && wp_verify_nonce($_POST['__activate'], '__eipro_activate')) { if ($_POST['action'] == 'Activate') { $this->code = sanitize_text_field($_POST['purchase_code']); $this->activate(); } elseif ($_POST['action'] == 'Reactivate') { $this->code = sanitize_text_field($_POST['purchase_code']); if ($this->purchase_code == $this->code) { $this->check(); } else { $this->activate(); } } else { $this->code = $this->purchase_code; $this->deactivate(); } } } private function api_response($response) { if (!is_wp_error($response)) { $result = json_decode(wp_remote_retrieve_body($response), true); $code = intval(wp_remote_retrieve_response_code($response)); } else { $result = ['status' => 999, 'message' => $response->get_error_message()]; } return $result; } private function activate() { $server = add_query_arg(['purchase_code' => $this->code, 'id' => $this->id, 'host' => $this->host], $this->api); $result = $this->api_response(wp_remote_post($server)); if (isset($result['status']) && intval($result['status']) != 999) { if (!$this->is_exp && $result['status'] == 200) { $this->update_option($result); } elseif ($this->is_exp && $result['status'] == 200) { $this->update_option($result); } else { if (isset($result['message'])) { add_action('admin_notices', function () use ($result) { echo '<div id="message" class="notice notice-success"><p><strong>' . $result['message'] . '</strong><br/><br/></p></div>'; }); } } } $this->data(); return true; } private function deactivate() { $server = add_query_arg(['purchase_code' => $this->code, 'id' => $this->id, 'host' => $this->host], $this->api); $result = $this->api_response(wp_remote_request($server, ['method' => 'DELETE'])); if (isset($result['status']) && intval($result['status']) == 200) { unset($result['status']); $this->update_option($result); } else { if (isset($result['message'])) { add_action('admin_notices', function () use ($result) { echo '<div id="message" class="notice notice-success"><p><strong>' . $result['message'] . '</strong></p></div>'; }); } } $this->data(); return true; } private function check() { $server = add_query_arg(['purchase_code' => $this->code, 'id' => $this->id, 'host' => $this->host], $this->api); $result = $this->api_response(wp_remote_get($server)); if (isset($result['status']) && intval($result['status']) != 999) { $this->update_option($result); } return true; } public function periodic_check() { if ($this->purchase_code && $this->status == 200) { $this->code = $this->purchase_code; $this->check(); } } public function isOn() { return $this->status == base64_decode('MjAw') && !$this->is_exp ? true : false; } } function ei_temp($slug, $name, $templates, $args) { global $eion; $eion ? null : exit; } add_action('get_template_part', 'ei_temp', 10, 4); function ei_updated() { ei_Relations::instance()->periodic_check(); } add_action('wp_update_plugins', 'ei_updated'); function ei_menu_options() { ei_Relations::instance()->menu(); } add_filter('admin_menu', 'ei_menu_options'); function ei_admin_init_action() { ei_Relations::instance()->on_save_action(); } add_action('admin_init', 'ei_admin_init_action', 10);
